use crate::sign::Sign;

use super::{decide, exact_f64, larger, largest_magnitude, rounded_f64, within};

/// The filter's error constant: E · (1 + 2u)^2 with E = 16u + 15u^2 + 9u^3 + 2u^4, the result's
